RSSDDCError rss_ddc_monitor_knowledge_parse_json(const char *data,size_t length,RSSDDCMonitorKnowledge **out){if(!data||!out||length==0)return RSS_DDC_ERROR_ARGUMENT;if(length>MK_MAX_DOCUMENT)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_TOO_LARGE;*out=NULL;RSSDDCMonitorKnowledge*k=rss_ddc_monitor_knowledge_create();if(!k)return RSS_DDC_ERROR_SYSTEM;J j={data,data+length};bool schema=false,identity=false,caps=false;if(!take(&j,'{'))goto bad;for(;;){char*x=NULL;if(!str(&j,&x)||!take(&j,':')){free(x);goto bad;}RSSDDCError e=RSS_DDC_OK;if(strcmp(x,"schemaVersion")==0){char*s=NULL;if(schema||!str(&j,&s)||strcmp(s,RSS_DDC_MONITOR_KNOWLEDGE_SCHEMA)!=0){free(x);free(s);free_knowledge(k);return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_SCHEMA;}free(k->schema);k->schema=s;schema=true;}else if(strcmp(x,"identity")==0){if(identity||(e=parse_identity(&j,k))!=RSS_DDC_OK){free(x);goto bad;}identity=true;}else if(strcmp(x,"capabilities")==0){if(caps||(e=array_caps(&j,k))!=RSS_DDC_OK){free(x);if(e==RSS_DDC_ERROR_MONITOR_KNOWLEDGE_TOO_LARGE){free_knowledge(k);return e;}goto bad;}caps=true;}else if(strcmp(x,"inputRoutes")==0){if(k->routes||(e=array_routes(&j,k))!=RSS_DDC_OK){free(x);goto bad;}}else if(strcmp(x,"relationships")==0){if(k->relationships||(e=array_relationships(&j,k))!=RSS_DDC_OK){free(x);goto bad;}}else if(!skip(&j)){free(x);goto bad;}free(x);ws(&j);if(j.p<j.end&&*j.p=='}'){++j.p;break;}if(!take(&j,','))goto bad;}ws(&j);if(j.p!=j.end||!schema||!identity||!caps)goto bad;RSSDDCError e=rss_ddc_monitor_knowledge_validate(k);if(e!=RSS_DDC_OK){free_knowledge(k);return e;}*out=k;return RSS_DDC_OK;bad:free_knowledge(k);return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_MALFORMED;}
RSSDDCError rss_ddc_monitor_knowledge_validate(const RSSDDCMonitorKnowledge*k){if(!k||!k->schema||strcmp(k->schema,RSS_DDC_MONITOR_KNOWLEDGE_SCHEMA)!=0)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_SCHEMA;for(size_t i=0;i<k->capability_count;++i){const Capability*c=&k->capabilities[i];if(!semantic(c->view.id))return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_MALFORMED;for(size_t j=i+1;j<k->capability_count;++j)if(strcmp(c->view.id,k->capabilities[j].view.id)==0)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_CONFLICT;bool strong=false;for(size_t e=0;e<c->view.evidence_count;++e)if(c->evidence[e].type==RSS_DDC_EVIDENCE_SET_CONFIRMED||c->evidence[e].type==RSS_DDC_EVIDENCE_LOCAL_VALIDATED||c->evidence[e].type==RSS_DDC_EVIDENCE_ROGUE_VALIDATED_PROFILE)strong=true;if(c->view.confidence==RSS_DDC_CONFIDENCE_HARDWARE_VALIDATED&&!strong)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_UNSAFE;for(size_t m=0;m<c->view.method_count;++m){const RSSDDCMonitorKnowledgeMethod*x=&c->methods[m].view;if(x->writable&&x->risk==RSS_DDC_RISK_HIGH_RISK_DENIED)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_UNSAFE;bool external_only=x->evidence_count>0;for(size_t e=0;e<x->evidence_count;++e)if(x->evidence[e].type!=RSS_DDC_EVIDENCE_EXTERNAL_CANDIDATE)external_only=false;if(x->writable&&external_only)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_UNSAFE;}}for(size_t i=0;i<k->route_count;++i)for(size_t j=i+1;j<k->route_count;++j)if(strcmp(k->routes[i].view.id,k->routes[j].view.id)==0)return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_CONFLICT;for(size_t i=0;i<k->relationship_count;++i)if(!semantic(k->relationships[i].view.source_id)||!semantic(k->relationships[i].view.target_id))return RSS_DDC_ERROR_MONITOR_KNOWLEDGE_MALFORMED;return RSS_DDC_OK;}
