typedef struct { char *p; size_t cap,n; } W; static bool put(W*w,const char*s){size_t n=strlen(s);if(w->p&&w->n+n<w->cap)memcpy(w->p+w->n,s,n);w->n+=n;return true;}static bool putn(W*w,int64_t n){char b[32];snprintf(b,sizeof(b),"%lld",(long long)n);return put(w,b);}static void raw_out(W*w,const RSSDDCRawValue*r){put(w,"{\"type\":\"");put(w,raw_names[r->type]);put(w,"\",\"value\":");if(r->type==RSS_DDC_RAW_UNSIGNED)putn(w,(int64_t)r->unsigned_value);else if(r->type==RSS_DDC_RAW_SIGNED)putn(w,r->signed_value);else{put(w,"\"");put(w,(const char*)r->data);put(w,"\"");}put(w,"}");}
